{
  "summary": "Position CA2026-120 covers the Trustee Area 3 Governing Board Member race in California. Three candidates are on record: Mark Fay, Wendy Huang, and Harris Mojadedi; none has a party affiliation listed. For Mojadedi, CAIR Action is recorded as having endorsed him in the general phase, and Vote for Peace lists him as an Ally in the general phase. The guide publisher's record, reviewed on 2026-11-02, notes an owner-reported statement that the Muslim American Alliance strongly opposes Mojadedi; it is not independently verified and has no public source link. A 2024 Bay Area Reporter article documents Mojadedi's public criticism of the MAA guide's parental-rights criteria; it is classified as a community-policy disagreement that does not verify the opposition or establish a Gaza position. The publisher disposition records a No recommendation setting for this race.",
  "evidence_audit": [
    {
      "id": "candidate_records.Mark Fay",
      "note": "Recorded as a candidate for Trustee Area 3 Governing Board Member, California. No party affiliation, endorsements, platform points, or other recorded items on file."
    },
    {
      "id": "candidate_records.Wendy Huang",
      "note": "Recorded as a candidate for Trustee Area 3 Governing Board Member, California. No party affiliation, endorsements, platform points, or other recorded items on file."
    },
    {
      "id": "candidate_records.Harris Mojadedi",
      "note": "Recorded with campaign platform points on education, immigration, economy, housing, jobs, AI policy, and government accountability. CAIR Action recorded as endorsed (general); Vote for Peace recorded as Ally (general)."
    },
    {
      "id": "community_source_report",
      "note": "Owner-reported MAA opposition to Mojadedi recorded by the guide publisher on 2026-11-02; no public source link; not independently verified. A 2024 Bay Area Reporter article documents Mojadedi's public criticism of the MAA guide's parental-rights criteria, classified as a community-policy disagreement; it does not verify the opposition or establish a Gaza position."
    },
    {
      "id": "publisher_disposition",
      "note": "No recommendation setting recorded by the publisher on 2026-11-02, attributed to the owner-reported MAA opposition. This is a publisher decision, not an inference from the 2024 article or a new Gaza assessment."
    }
  ]
}
